import functools
import jwt
from flask import request, g, jsonify, current_app

from app.models.user import User, find_user_by_id


class AuthError(Exception):
    def __init__(self, message, status_code=401):
        super().__init__(message)
        self.message = message
        self.status_code = status_code


def decode_token(token):
    try:
        payload = jwt.decode(
            token,
            current_app.config["JWT_SECRET"],
            algorithms=[current_app.config["JWT_ALGORITHM"]],
        )
        return payload
    except jwt.ExpiredSignatureError:
        raise AuthError("Token has expired")
    except jwt.InvalidTokenError:
        raise AuthError("Invalid token")


def jwt_required(f):
    @functools.wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            raise AuthError("Missing or invalid Authorization header")

        token = auth_header.split(" ", 1)[1]
        if not token:
            raise AuthError("Missing token")

        payload = decode_token(token)
        user = find_user_by_id(payload["sub"])
        if user is None:
            raise AuthError("User not found")

        g.current_user = user
        return f(*args, **kwargs)

    return decorated


def create_access_token(user_id):
    import datetime

    now = datetime.datetime.now(datetime.timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + current_app.config["JWT_ACCESS_TOKEN_EXPIRES"],
        "type": "access",
    }
    return jwt.encode(
        payload, current_app.config["JWT_SECRET"], algorithm=current_app.config["JWT_ALGORITHM"]
    )


def create_refresh_token(user_id):
    import datetime

    now = datetime.datetime.now(datetime.timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + current_app.config["JWT_REFRESH_TOKEN_EXPIRES"],
        "type": "refresh",
    }
    return jwt.encode(
        payload, current_app.config["JWT_SECRET"], algorithm=current_app.config["JWT_ALGORITHM"]
    )

from flask import jsonify
from werkzeug.exceptions import HTTPException

from app.middleware.auth import AuthError


class APIError(Exception):
    def __init__(self, message, status_code=400, details=None):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.details = details or {}


def register_error_handlers(app):
    @app.errorhandler(AuthError)
    def handle_auth_error(error):
        return jsonify({"error": error.message}), error.status_code

    @app.errorhandler(APIError)
    def handle_api_error(error):
        payload = {"error": error.message}
        if error.details:
            payload["details"] = error.details
        return jsonify(payload), error.status_code

    @app.errorhandler(HTTPException)
    def handle_http_exception(error):
        return (
            jsonify(
                {
                    "error": error.name.replace("_", " ").capitalize(),
                    "description": error.description,
                }
            ),
            error.code,
        )

    @app.errorhandler(429)
    def handle_rate_limit_error(error):
        return jsonify({"error": "Rate limit exceeded. Try again later."}), 429

    @app.errorhandler(404)
    def handle_not_found(error):
        return jsonify({"error": "Resource not found"}), 404

    @app.errorhandler(405)
    def handle_method_not_allowed(error):
        return jsonify({"error": "Method not allowed"}), 405

    @app.errorhandler(500)
    def handle_internal_error(error):
        return jsonify({"error": "Internal server error"}), 500

from copy import deepcopy

_users: dict[str, dict] = {}
_items: dict[str, dict] = {}
_next_user_id = 1
_next_item_id = 1


def _next_uid():
    global _next_user_id
    uid = str(_next_user_id)
    _next_user_id += 1
    return uid


def _next_iid():
    global _next_item_id
    iid = str(_next_item_id)
    _next_item_id += 1
    return iid


def create_user(username, hashed_password):
    uid = _next_uid()
    user = {"id": uid, "username": username, "password": hashed_password}
    _users[uid] = user
    return deepcopy(user)


def find_user_by_username(username):
    for u in _users.values():
        if u["username"] == username:
            return deepcopy(u)
    return None


def find_user_by_id(user_id):
    u = _users.get(user_id)
    return deepcopy(u) if u else None


def get_all_users():
    return [deepcopy(u) for u in _users.values()]


def create_item(name, description, owner_id):
    iid = _next_iid()
    item = {"id": iid, "name": name, "description": description, "owner_id": owner_id}
    _items[iid] = item
    return deepcopy(item)


def get_item(item_id):
    item = _items.get(item_id)
    return deepcopy(item) if item else None


def get_items_paginated(page, per_page, owner_id=None):
    items = list(_items.values())
    if owner_id is not None:
        items = [i for i in items if i["owner_id"] == owner_id]
    items.sort(key=lambda i: int(i["id"]))

    total = len(items)
    start = (page - 1) * per_page
    end = start + per_page
    page_items = items[start:end]

    return {
        "data": deepcopy(page_items),
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "pages": max(1, (total + per_page - 1) // per_page),
        },
    }


def update_item(item_id, **kwargs):
    item = _items.get(item_id)
    if not item:
        return None
    for k, v in kwargs.items():
        if v is not None:
            item[k] = v
    return deepcopy(item)


def delete_item(item_id):
    item = _items.pop(item_id, None)
    return deepcopy(item) if item else None


def reset_store():
    global _users, _items, _next_user_id, _next_item_id
    _users = {}
    _items = {}
    _next_user_id = 1
    _next_item_id = 1

def parse_pagination_args():
    from flask import request

    try:
        page = int(request.args.get("page", 1))
    except (ValueError, TypeError):
        page = 1
    try:
        per_page = int(request.args.get("per_page", 20))
    except (ValueError, TypeError):
        per_page = 20

    page = max(1, page)
    per_page = max(1, min(100, per_page))
    return page, per_page

from marshmallow import Schema, fields, validate, validates_schema, ValidationError


class RegisterSchema(Schema):
    username = fields.Str(
        required=True, validate=validate.Length(min=3, max=50)
    )
    password = fields.Str(
        required=True, validate=validate.Length(min=8, max=128)
    )


class LoginSchema(Schema):
    username = fields.Str(required=True)
    password = fields.Str(required=True)


class RefreshSchema(Schema):
    refresh_token = fields.Str(required=True)


class ItemCreateSchema(Schema):
    name = fields.Str(
        required=True, validate=validate.Length(min=1, max=200)
    )
    description = fields.Str(
        missing="", validate=validate.Length(max=2000)
    )


class ItemUpdateSchema(Schema):
    name = fields.Str(validate=validate.Length(min=1, max=200))
    description = fields.Str(validate=validate.Length(max=2000))

import bcrypt
from flask import request, jsonify, g

from app.api.v1 import bp
from app.api.v1.schemas import RegisterSchema, LoginSchema, RefreshSchema
from app.middleware.auth import (
    create_access_token,
    create_refresh_token,
    decode_token,
    jwt_required,
)
from app.middleware.error_handler import APIError
from app.middleware.logging import audit_log
from app.models.user import create_user, find_user_by_username


@bp.route("/auth/register", methods=["POST"])
def register():
    data = RegisterSchema().load(request.get_json(silent=True) or {})
    if find_user_by_username(data["username"]):
        raise APIError("Username already taken", 409)

    hashed = bcrypt.hashpw(data["password"].encode(), bcrypt.gensalt()).decode()
    user = create_user(data["username"], hashed)

    audit_log("user_registered", username=user["username"])

    return (
        jsonify(
            {
                "user": {"id": user["id"], "username": user["username"]},
                "access_token": create_access_token(user["id"]),
                "refresh_token": create_refresh_token(user["id"]),
            }
        ),
        201,
    )


@bp.route("/auth/login", methods=["POST"])
def login():
    data = LoginSchema().load(request.get_json(silent=True) or {})
    user = find_user_by_username(data["username"])
    if not user or not bcrypt.checkpw(
        data["password"].encode(), user["password"].encode()
    ):
        raise APIError("Invalid credentials", 401)

    audit_log("user_login", username=user["username"])

    return jsonify(
        {
            "user": {"id": user["id"], "username": user["username"]},
            "access_token": create_access_token(user["id"]),
            "refresh_token": create_refresh_token(user["id"]),
        }
    )


@bp.route("/auth/refresh", methods=["POST"])
def refresh():
    data = RefreshSchema().load(request.get_json(silent=True) or {})
    payload = decode_token(data["refresh_token"])
    if payload.get("type") != "refresh":
        raise APIError("Token is not a refresh token", 401)

    access_token = create_access_token(payload["sub"])
    refresh_token = create_refresh_token(payload["sub"])

    return jsonify({"access_token": access_token, "refresh_token": refresh_token})


@bp.route("/auth/me", methods=["GET"])
@jwt_required
def me():
    user = g.current_user
    return jsonify({"user": {"id": user["id"], "username": user["username"]}})

from flask import request, jsonify, g

from app.api.v1 import bp
from app.api.v1.schemas import ItemCreateSchema, ItemUpdateSchema
from app.middleware.auth import jwt_required
from app.middleware.error_handler import APIError
from app.middleware.logging import audit_log
from app.models.user import (
    create_item,
    get_item,
    get_items_paginated,
    update_item,
    delete_item,
)
from app.utils.pagination import parse_pagination_args


@bp.route("/items", methods=["POST"])
@jwt_required
def create():
    data = ItemCreateSchema().load(request.get_json(silent=True) or {})
    item = create_item(data["name"], data.get("description", ""), g.current_user["id"])

    audit_log("item_created", item_id=item["id"], name=item["name"])

    return jsonify({"item": item}), 201


@bp.route("/items", methods=["GET"])
@jwt_required
def list_items():
    page, per_page = parse_pagination_args()
    result = get_items_paginated(page, per_page)
    return jsonify(result)


@bp.route("/items/<item_id>", methods=["GET"])
@jwt_required
def get_one(item_id):
    item = get_item(item_id)
    if not item:
        raise APIError("Item not found", 404)
    return jsonify({"item": item})


@bp.route("/items/<item_id>", methods=["PUT"])
@jwt_required
def update(item_id):
    item = get_item(item_id)
    if not item:
        raise APIError("Item not found", 404)
    if item["owner_id"] != g.current_user["id"]:
        raise APIError("Forbidden", 403)

    data = ItemUpdateSchema().load(request.get_json(silent=True) or {})
    updated = update_item(item_id, **data)

    audit_log("item_updated", item_id=item_id)

    return jsonify({"item": updated})


@bp.route("/items/<item_id>", methods=["DELETE"])
@jwt_required
def delete(item_id):
    item = get_item(item_id)
    if not item:
        raise APIError("Item not found", 404)
    if item["owner_id"] != g.current_user["id"]:
        raise APIError("Forbidden", 403)

    deleted = delete_item(item_id)

    audit_log("item_deleted", item_id=item_id)

    return jsonify({"item": deleted})

